import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.DnrXFDHb.js";const o="/images/screenshots/codex-client-download.png",d="/images/screenshots/codex-client-open-project.png",n="/images/screenshots/codex-cli-start.png",k=JSON.parse('{"title":"安装 ChatGPT","description":"面向零基础用户的 ChatGPT 安装指南（桌面端含 Codex 功能）。不管你有没有编程经验，跟着一步步来就能装好。","frontmatter":{"title":"安装 ChatGPT","description":"面向零基础用户的 ChatGPT 安装指南（桌面端含 Codex 功能）。不管你有没有编程经验，跟着一步步来就能装好。"},"headers":[],"relativePath":"guide/codex-install.md","filePath":"guide/codex-install.md","lastUpdated":1783585126000}'),l={name:"guide/codex-install.md"};function r(h,t,p,c,g,C){return s(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="安装-chatgpt" tabindex="-1">安装 ChatGPT <a class="header-anchor" href="#安装-chatgpt" aria-label="Permalink to &quot;安装 ChatGPT&quot;">​</a></h1><p>欢迎！这一页帮你把 ChatGPT 装到电脑上。ChatGPT 桌面应用里自带 Codex（读作&quot;扣 dex&quot;，OpenAI 出的一个 <strong>AI 编程工具</strong>，你说话，它写代码），不用单独安装。</p><h2 id="先帮你做个选择-用桌面应用还是命令行" tabindex="-1">先帮你做个选择：用桌面应用还是命令行？ <a class="header-anchor" href="#先帮你做个选择-用桌面应用还是命令行" aria-label="Permalink to &quot;先帮你做个选择：用桌面应用还是命令行？&quot;">​</a></h2><p>用 ChatGPT 有两种方式，<strong>选一种就行</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>适合谁</th><th>长什么样</th></tr></thead><tbody><tr><td><strong>ChatGPT 桌面应用</strong>（里面自带 Codex）</td><td>✅ <strong>绝大多数用户</strong>，包括第一次接触编程的你</td><td>跟普通软件一样，有窗口、有按钮、可以鼠标点</td></tr><tr><td><strong>Codex CLI</strong>（命令行，Command Line Interface 的缩写）</td><td>习惯在黑色窗口里敲命令的人，或者用 Linux / 远程服务器的人</td><td>在终端（那个黑底白字的窗口）里敲命令操作</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">🎯 直接给你结论</p><p><strong>选 ChatGPT 桌面应用。</strong> Codex 功能现在就在 ChatGPT 桌面应用里，不用单独装。除非你很清楚自己要用命令行（比如你是程序员，或者用 Linux），不然用桌面应用就够了。下面先讲桌面应用怎么装，命令行放在后面备用。</p></div><h2 id="方式一-安装-chatgpt-桌面应用-推荐-✅" tabindex="-1">方式一：安装 ChatGPT 桌面应用（推荐 ✅） <a class="header-anchor" href="#方式一-安装-chatgpt-桌面应用-推荐-✅" aria-label="Permalink to &quot;方式一：安装 ChatGPT 桌面应用（推荐 ✅）&quot;">​</a></h2><h3 id="打开下载页面" tabindex="-1">打开下载页面 <a class="header-anchor" href="#打开下载页面" aria-label="Permalink to &quot;打开下载页面&quot;">​</a></h3><p>用浏览器打开 ChatGPT 桌面应用的官方下载页面：</p><p>👉 <a href="https://openai.com/chatgpt/download/" target="_blank" rel="noreferrer">https://openai.com/chatgpt/download/</a></p><p>打开后你会看到页面标题写着「Download ChatGPT for desktop」，上面有 macOS 和 Windows 两个下载入口。</p><p><strong>根据你的电脑系统，点对应的按钮：</strong></p><table tabindex="0"><thead><tr><th>你的电脑</th><th>点哪个</th></tr></thead><tbody><tr><td>🍎 Mac 电脑</td><td>点 <strong>「macOS」</strong> 下载按钮，会下载一个安装文件</td></tr><tr><td>🪟 Windows 电脑</td><td>点 <strong>「Windows」</strong> 下载按钮，会跳转到 Microsoft Store（微软应用商店），在商店里点 <strong>「获取」</strong> 或 <strong>「安装」</strong></td></tr><tr><td>🐧 Linux 电脑</td><td>ChatGPT 桌面应用没有 Linux 版，直接看下方的 <a href="#方式二安装-codex-cli备选">命令行方式</a></td></tr></tbody></table><p><img src="'+o+'" alt="ChatGPT 桌面应用下载页面" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">⚠️ Windows 用户注意</p><p>ChatGPT 桌面应用要求 Windows 10 或更高版本。</p><ul><li>如果你的电脑是 <strong>Windows 10 或 Windows 11</strong> → 没问题，继续。</li><li>如果是 <strong>Windows 8</strong> → 不能用桌面应用，看下方的 <a href="#方式二安装-codex-cli备选">命令行方式</a>。</li><li>如果是 <strong>Windows 7 或更早</strong> → 需要先升级系统才能用。</li></ul></div><div class="tip custom-block"><p class="custom-block-title">💡 Microsoft Store 打不开或下载太慢？</p><p>别着急，先看下方的 <a href="#方式二安装-codex-cli备选">命令行方式</a> 装 Codex CLI，一样能用。等商店恢复正常了再换回桌面应用。</p></div><h3 id="安装并打开-chatgpt" tabindex="-1">安装并打开 ChatGPT <a class="header-anchor" href="#安装并打开-chatgpt" aria-label="Permalink to &quot;安装并打开 ChatGPT&quot;">​</a></h3><p>下载完成后：</p><ul><li><strong>Mac</strong>：会得到一个 <code>.dmg</code> 文件，双击打开，把 ChatGPT 图标拖进「应用程序」文件夹。</li><li><strong>Windows</strong>：Microsoft Store 会自动安装，装好后在开始菜单里能找到 ChatGPT。</li></ul><p>安装完成后，<strong>双击 ChatGPT 图标打开它</strong>。第一次打开时，ChatGPT 会引导你登录 OpenAI 账号（或者创建新账号），按屏幕上的提示操作就行。</p><p>你会看到 ChatGPT 的主界面，这说明安装成功了 ✅。</p><h3 id="在-chatgpt-里进入-codex-打开项目文件夹" tabindex="-1">在 ChatGPT 里进入 Codex，打开项目文件夹 <a class="header-anchor" href="#在-chatgpt-里进入-codex-打开项目文件夹" aria-label="Permalink to &quot;在 ChatGPT 里进入 Codex，打开项目文件夹&quot;">​</a></h3><p>在 ChatGPT 桌面应用里找到并进入 <strong>Codex</strong>（界面里通常有明显的 Codex 入口）。进入后，它会让你选择一个文件夹来工作。这个文件夹就是 Codex 帮你写代码的地方。</p><ul><li><strong>如果你有项目文件夹</strong>：直接选你的项目文件夹。</li><li><strong>如果你还没有</strong>：在桌面上新建一个空文件夹（右键 → 新建文件夹 → 随便起个名字比如&quot;我的项目&quot;），然后在 Codex 里选它。</li></ul><p><img src="'+d+'" alt="在 ChatGPT 里打开项目文件夹" loading="lazy"></p><p>选好文件夹后，Codex 的主工作界面就会出现。</p><div class="tip custom-block"><p class="custom-block-title">✅ 检查点</p><p>到这一步，你只需要确认两件事：</p><ol><li>ChatGPT 能正常打开，不是闪退或白屏。</li><li>能进入 Codex，并选一个文件夹，看到 Codex 的工作界面。</li></ol><p><strong>做到这两步就够了。</strong> 接下来要让 ChatGPT 连上 CCWS 才能开始用，继续看下面的「下一步」。</p></div><hr><h2 id="方式二-安装-codex-cli-备选" tabindex="-1">方式二：安装 Codex CLI（备选） <a class="header-anchor" href="#方式二-安装-codex-cli-备选" aria-label="Permalink to &quot;方式二：安装 Codex CLI（备选）&quot;">​</a></h2><p>Codex CLI（命令行版本）是给习惯在终端（那个黑底白字的窗口）里敲命令的人准备的。下面这些情况才用得上它：</p><table tabindex="0"><thead><tr><th>你的情况</th><th>需要 CLI 吗？</th></tr></thead><tbody><tr><td>用 Linux 系统</td><td>✅ 需要，ChatGPT 桌面应用没有 Linux 版</td></tr><tr><td>Mac / Windows，但桌面应用装不上</td><td>✅ 可以先用 CLI</td></tr><tr><td>程序员，本来就天天用终端</td><td>✅ 可以用 CLI</td></tr><tr><td>普通用户，桌面应用已经装好了</td><td>❌ 不需要，跳过这一整节</td></tr></tbody></table><h3 id="打开终端" tabindex="-1">打开终端 <a class="header-anchor" href="#打开终端" aria-label="Permalink to &quot;打开终端&quot;">​</a></h3><p>先找到你电脑上的终端程序（那个用来敲命令的窗口）：</p><table tabindex="0"><thead><tr><th>你的电脑</th><th>怎么打开终端</th></tr></thead><tbody><tr><td>🍎 Mac</td><td>按 <code>Command + 空格</code>，搜索 <strong>「终端」</strong> 或 <strong>「Terminal」</strong>，回车打开</td></tr><tr><td>🪟 Windows</td><td>按 <code>Win 键</code>，搜索 <strong>「PowerShell」</strong>，回车打开</td></tr></tbody></table><p>打开后你会看到一个黑底白字（或白底黑字）的窗口，里面有一行闪烁的光标，这就是终端。</p><h3 id="运行安装命令" tabindex="-1">运行安装命令 <a class="header-anchor" href="#运行安装命令" aria-label="Permalink to &quot;运行安装命令&quot;">​</a></h3><p><strong>把下面这行命令完整复制</strong>（从 <code>curl</code> 开始到 <code>sh</code> 结束），粘贴到终端窗口里，按回车：</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-w7DF1" id="tab-H5VwKvS" checked><label data-title="Mac" for="tab-H5VwKvS">Mac</label><input type="radio" name="group-w7DF1" id="tab-HEdOkxz"><label data-title="Windows" for="tab-HEdOkxz">Windows</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://chatgpt.com/codex/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy ByPass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;irm https://chatgpt.com/codex/install.ps1 | iex&quot;</span></span></code></pre></div></div></div><p>按回车后，屏幕上会跑一些文字，这是在自动下载和安装。<strong>看到命令提示符重新出现（就是你又能输入东西了），说明安装完成。</strong></p><div class="tip custom-block"><p class="custom-block-title">💡 安装完成后</p><p><strong>关掉当前终端窗口，重新打开一个新的终端。</strong> 这步很重要，不然系统可能找不到刚刚装好的 Codex CLI。</p></div><h3 id="验证装好了没" tabindex="-1">验证装好了没 <a class="header-anchor" href="#验证装好了没" aria-label="Permalink to &quot;验证装好了没&quot;">​</a></h3><p>在新终端里输入下面这行，按回车：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>如果你看到类似 <code>1.0.0</code> 这样的版本号，说明装好了 ✅。</p><p><img src="'+n+'" alt="Codex CLI 启动成功" loading="lazy"></p><p>如果提示 <code>command not found</code>（找不到命令），说明没装上，回到上面重新来一遍。</p><h3 id="补充-用-npm-安装-只有当你本来就用-npm-才选这个" tabindex="-1">补充：用 npm 安装（只有当你本来就用 npm 才选这个） <a class="header-anchor" href="#补充-用-npm-安装-只有当你本来就用-npm-才选这个" aria-label="Permalink to &quot;补充：用 npm 安装（只有当你本来就用 npm 才选这个）&quot;">​</a></h3><p>如果你电脑上已经装了 Node.js 和 npm（前端开发用的工具），也可以用 npm 安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @openai/codex</span></span></code></pre></div><p>如果你不知道 npm 是什么，这一段直接跳过，用上面的官方脚本安装就行。</p><div class="tip custom-block"><p class="custom-block-title">🔗 需要装 Node.js？</p><p>如果你确实需要用 npm 方式安装 Codex CLI，但电脑上还没有 Node.js，去看 <a href="/guide/nodejs-git">Node.js 环境准备（CLI 用户可选）</a>。</p></div><hr><h2 id="装好了-接下来做什么" tabindex="-1">装好了，接下来做什么？ <a class="header-anchor" href="#装好了-接下来做什么" aria-label="Permalink to &quot;装好了，接下来做什么？&quot;">​</a></h2><p>恭喜，ChatGPT 已经装好了 🎉 现在按顺序继续：</p><p><strong>👉 下一步：<a href="/guide/register">注册 CCWS 账号</a></strong>——去 CCWS 官网注册一个账号，后面配置要用。</p><p>完整流程：</p><ol><li>✅ 安装 ChatGPT（你在这里）</li><li>⬜ <a href="/guide/register">注册 CCWS 账号</a></li><li>⬜ <a href="/guide/recharge">给账号充值</a></li><li>⬜ <a href="/guide/api-key">创建 API Key</a></li><li>⬜ <a href="/guide/connect">配置 ChatGPT 连接 CCWS</a> —— 发一条测试消息，ChatGPT 能回复你就全部完成了</li></ol><blockquote><p>如果你用的是 Linux 系统或者 npm 方式安装的 Codex CLI，在继续之前先看一眼 <a href="/guide/nodejs-git">Node.js 环境准备</a>，确认环境没问题。</p></blockquote>',58)])])}const b=a(l,[["render",r]]);export{k as __pageData,b as default};
